static UserCard ToCard(User u) => new(u.Id, u.Email);   // view = the DTO's property set

[HttpGet("{id:guid}")]
public async Task<IActionResult> Get(Guid id, string? fields) => fields switch
{
    "id,email" => Ok(ToCard(await _db.Users.FindAsync(id))),
    null       => Ok(await _db.Users.FindAsync(id)),
    _          => BadRequest($"unknown selection '{fields}'")
};
